def finding(k,text,keys,anchors,qualification='Inspected original record; profile identity remains qualified where stated.'):
 f=dict(id=k,date='2026-09-30',finding=text,qualification=qualification,sources=[{q:v for q,v in S[z].items() if q in ['title','url','entry_image_ref','original_inspected']} for z in keys],subject_refs=anchors)
 latest.append(f)
 for g,p in anchors:extra.setdefault((g,p),[]).append(dict(finding_id=k,finding=text,qualification=qualification,sources=f['sources']))
def R(child,parent,grade,basis,prior='not previously graded; no earlier father assertion for this particular census child',ids=None):
 rel.append(dict(child=child,parent=parent,prior_assessed_on='2026-09-30 baseline',prior_assessment=prior,new_assessed_on='2026-09-30',new_assessment=grade,source_ids=basis,profile_identity=ids or 'not identified; documentary relationship only',counts_as_existing_profile_certainty_upgrade=False))
G='gortereghy-elder-and-anderson'
finding('irish-gortereghy-robert-elder-children-1901','The original 1901 Gortereghy return records Robert Elder, 65, widowed farmer, with Alex 27 and Robert 20 as sons and Eliza 22 and Margaretta 14 as daughters. The 1911 Alexander/Mary household explicitly records Robert as Alexander’s brother and Margaret as his sister. The combined names and locality strongly support continuity, with age differences retained. Robert Elder-7144 remains a qualified father identity; Robert/Mary Glasgow’s Gortahar household is separate.',['nai000298460','nai001390156'],[(G,'robert-elder-father'),(G,'alexander-elder'),(G,'robert-elder-brother')])
for ch in ['Alex Elder, 27, 1901','Robert Elder, 20, 1901','Eliza Elder, 22, 1901','Margaretta Elder, 14, 1901']:R(ch,'Robert Elder, Gortereghy head 1901','documented father in original return',['nai000298460'],ids='Elder-7144 compatible, not proved; extend same uncertain identity across all four siblings')
finding('irish-gortereghy-elder-calderwood-jane-1881','The original birth entry names Jane Elder, born 27 April 1881 at Gortreighy, daughter of farmer Robert Elder and Jane formerly Calderwood. This identifies that parental couple and strengthens the separate Robert/Jane study; it does not yet prove Jane Calderwood as mother of all 1901/1911 siblings.',['jane-elder-1881'],[(G,'robert-elder-father')])
